//! Pure, testable policy for host DNAT rules (#2617).
//!
//! Two invariants are enforced here so they can be unit-tested without
//! touching a host or running `iptables`:
//!
//! 1. Every PREROUTING DNAT rule is generated by [`prerouting_dnat_args`],
//!    which always emits an `-i <external-iface>` ingress matcher.
//! 2. Internal/admin ports (Vault, DB, cache, ALM) are never DNATed from the
//!    public interface — [`public_dnat_verdict`] refuses them. They remain
//!    reachable only from the host / Incus network via OUTPUT + FORWARD rules.
//!
//! The interface and the destination are supplied by configuration
//! (`GB_EXTERNAL_IFACE` and container settings); no interface or IP literal is
//! hardcoded here.

/// Ports that bind internal/admin services. These must never be DNATed from a
/// public interface — they are reached through the proxy or from inside the
/// host/Incus network only.
pub const INTERNAL_ONLY_PORTS: &[u16] = &[
    6379, // cache (Valkey) — internal data store
    5432, // tables (PostgreSQL) — internal database
    8200, // vault — secrets, admin only
    4747, // alm (Forgejo) — admin only, sits behind the Caddy proxy
];

/// Pure verdict: may `port` be DNATed from the external (public) interface?
/// Internal/admin ports are refused so a public packet can never reach them,
/// even when the `-i` matcher is present.
pub fn public_dnat_verdict(port: u16) -> bool {
    !INTERNAL_ONLY_PORTS.contains(&port)
}

/// Valid Linux interface names: letters, digits, `-`, `_`, `.`, at most 15
/// chars. Pure so the guard is testable without touching a host.
pub fn is_valid_interface(name: &str) -> bool {
    // `"all"`/`"any"` are iptables wildcards, not real interface names; using
    // one as the ingress matcher would defeat the whole point of `-i`.
    let name = name.trim();
    !name.is_empty()
        && !matches!(name.to_ascii_lowercase().as_str(), "all" | "any")
        && name.len() <= 15
        && name
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, '-' | '_' | '.'))
}

/// Build the complete `iptables` argument vector for a single PREROUTING DNAT
/// rule. This is the *only* place a PREROUTING DNAT rule is assembled, and it
/// unconditionally includes `-i <iface>` before the chain is applied (#2617).
pub fn prerouting_dnat_args(
    iface: &str,
    protocol: &str,
    port: u16,
    destination: &str,
) -> Vec<String> {
    vec![
        "-t".to_string(),
        "nat".to_string(),
        "-A".to_string(),
        "PREROUTING".to_string(),
        "-i".to_string(),
        iface.to_string(),
        "-p".to_string(),
        protocol.to_string(),
        "--dport".to_string(),
        port.to_string(),
        "-j".to_string(),
        "DNAT".to_string(),
        "--to-destination".to_string(),
        destination.to_string(),
    ]
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn accepts_real_interface_names_and_rejects_injection() {
        assert!(is_valid_interface("eth0"));
        assert!(is_valid_interface("enp3s0"));
        assert!(is_valid_interface("br-abc.1"));
        assert!(!is_valid_interface(""));
        assert!(!is_valid_interface("eth0;drop"));
        assert!(!is_valid_interface("all"));
    }

    #[test]
    fn internal_admin_ports_are_never_publicly_dnated() {
        for port in INTERNAL_ONLY_PORTS {
            assert!(
                !public_dnat_verdict(*port),
                "port {port} must not be DNATed from the public interface"
            );
        }
    }

    #[test]
    fn public_service_ports_remain_dnatable() {
        for port in [80u16, 443, 3000, 4000, 5000, 8080, 9000, 9100, 6333, 7880, 8081] {
            assert!(public_dnat_verdict(port), "port {port} should be publicly DNATable");
        }
    }

    #[test]
    fn generated_prerouting_rule_snapshot_has_ingress_matcher() {
        let args = prerouting_dnat_args("eth0", "tcp", 443, "192.0.2.10:443");
        assert_eq!(
            args.join(" "),
            "-t nat -A PREROUTING -i eth0 -p tcp --dport 443 -j DNAT --to-destination 192.0.2.10:443"
        );
        let chain = args.iter().position(|a| a == "PREROUTING").expect("chain");
        let matcher = args.iter().position(|a| a == "-i").expect("ingress matcher");
        assert!(chain < matcher, "-i must follow the PREROUTING chain");
        assert_eq!(args[matcher + 1], "eth0");
    }

    #[test]
    fn every_public_port_produces_a_rule_with_an_interface() {
        for port in [80u16, 443, 8080, 9000] {
            let args = prerouting_dnat_args("enp3s0", "tcp", port, "192.0.2.10:80");
            assert!(args.iter().any(|a| a == "-i"), "missing -i for port {port}");
            assert!(
                args.iter().any(|a| a == "enp3s0"),
                "missing external interface for port {port}"
            );
        }
    }

    #[test]
    fn configure_source_does_not_bypass_the_pure_guards() {
        let source = std::fs::read_to_string(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/src/package_manager/container/configure_iptables_nat.rs"
        ))
        .expect("read configure_iptables_nat.rs");
        assert!(
            !source.contains("net.ipv4.conf.all"),
            "global route_localnet must never be set"
        );
        assert!(
            source.contains("public_dnat_verdict"),
            "configure_iptables_nat must filter internal ports"
        );
        assert!(
            source.contains("prerouting_dnat_args"),
            "PREROUTING DNAT must use the pure generator"
        );
        assert!(
            !source.contains("\"PREROUTING\""),
            "no inline PREROUTING rule may bypass the -i matcher"
        );
    }
}
